const state={view:'dashboard',resource:'complexes',page:1,pageSize:20,complexId:Number(sessionStorage.getItem('complexId')||0),statDate:sessionStorage.getItem('statDate')||new Date().toISOString().slice(0,10),charts:{},query:'monthly',roleCodes:[],readOnly:false};
const labels={complexes:['综合体建档','complexes'],buildings:['建筑管理','buildings'],areas:['功能区域','areas'],merchants:['商户管理','merchants'],devices:['计量设备','meter-devices'],energy:['能源消费','energy-records'],carbon:['碳核算','carbon-records'],budget:['碳预算','budgets'],alerts:['预警整改','alerts'],tasks:['整改任务','corrective-tasks'],projects:['节能项目','projects'],logs:['操作日志','logs']};
const columns={complexes:[['complex_code','综合体编码'],['complex_name','综合体名称'],['address','地址'],['gross_floor_area','建筑面积']],buildings:[['building_code','建筑编码'],['building_name','建筑名称'],['building_type','建筑类型'],['gross_floor_area','建筑面积']],areas:[['area_code','区域编码'],['area_name','区域名称'],['area_type','区域类型'],['floor_no','楼层'],['gross_area','面积']],merchants:[['merchant_code','商户编码'],['merchant_name','商户名称'],['merchant_category','分类'],['brand_name','品牌'],['operating_area','经营面积']],devices:[['device_code','设备编码'],['device_name','设备名称'],['device_type','设备类型'],['measuring_unit','计量单位'],['online_status','在线状态']],energy:[['record_code','记录编码'],['record_date','记录日期'],['consumption_amount','用量'],['consumption_unit','单位'],['audit_status','审核状态']],carbon:[['accounting_code','核算编码'],['accounting_date','核算日期'],['activity_data','活动数据'],['activity_data_unit','活动单位'],['carbon_emission_kg','碳排放']],budget:[['budget_code','预算编码'],['budget_year','年度'],['total_budget_emission_kg','年度预算'],['actual_emission_kg','实际排放'],['execution_rate','执行率']],alerts:[['event_code','事件编码'],['severity_level','预警等级'],['event_title','事件标题'],['occurred_at','发生时间'],['event_status','状态']],tasks:[['task_code','任务编码'],['task_title','任务标题'],['task_status','任务状态'],['planned_end_at','计划完成时间']],projects:[['project_code','项目编码'],['project_name','项目名称'],['project_type','项目类型'],['investment_amount','投资额'],['project_status','项目状态']],logs:[['operation_time','操作时间'],['username_snapshot','操作用户'],['module_name','模块'],['business_type','业务类型'],['operation_description','操作说明'],['operation_result','执行结果']]};
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),toast=m=>{const t=$('#toast');t.textContent=m;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2500)};
function fmt(v){if(v===null||v===undefined||v==='')return '—';if(typeof v==='number'||!isNaN(v)&&v!=='')return Number(v).toLocaleString('zh-CN',{maximumFractionDigits:3});return String(v).replace('T',' ')}
function status(v){const m={0:'停用',1:'启用',2:'处理中',3:'已完成',4:'已关闭'};return m[v]??v}
const operationTypeNames={insert:'新增',update:'修改',select:'查询',delete:'删除',login:'登录',logout:'退出',audit:'审核',export:'导出',generate:'生成'};
function displayCell(resource,key,value){if(resource==='logs'&&key==='business_type')return operationTypeNames[String(value).toLowerCase()]||value;if(resource==='logs'&&key==='operation_result')return Number(value)===1?'成功':'失败';return key.includes('status')?status(value):fmt(value)}
async function api(url,opt={}){const r=await fetch('api/'+url,opt);let d={};try{d=await r.json()}catch{}if(r.status===401){location.href='login.jsp';throw Error('登录状态已失效')}if(!d.success)throw Error(d.message||'请求失败');return d.data}
function qs(extra=''){return `complexId=${state.complexId}&statDate=${state.statDate}${extra?'&'+extra:''}`}
function route(view,replace=false){const valid=['dashboard',...Object.keys(labels),'meters','queries','profile','merchant-bills','monthly-reports','data-quality'];if(!valid.includes(view))view='dashboard';state.view=view;sessionStorage.setItem('lastView',view);if(location.hash.slice(2)!==view){(replace?history.replaceState:history.pushState).call(history,null,'','#/'+view)}show(view)}
function show(view){document.querySelectorAll('.view').forEach(x=>x.classList.remove('active'));const dedicated=['meters','queries','profile','merchant-bills','monthly-reports','data-quality'];const el=$('#'+(dedicated.includes(view)?view:view==='dashboard'?'dashboard':'generic'));if(el)el.classList.add('active');document.querySelectorAll('#nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));const titles={'meters':'分级计量体系','queries':'专题查询中心','profile':'个人中心','dashboard':'总览驾驶舱','merchant-bills':'商户能碳账单','monthly-reports':'月度碳报告中心','data-quality':'数据质量中心'};$('#pageTitle').textContent=titles[view]||labels[view]?.[0]||'数据列表';if($('#add'))$('#add').hidden=view==='logs';if(view==='dashboard')loadDashboard();else if(view==='meters')loadTree();else if(view==='queries')loadQueries();else if(view==='profile')loadProfile();else if(view==='merchant-bills')loadMerchantBills();else if(view==='monthly-reports')initMonthlyReport();else if(view==='data-quality')loadDataQuality();else if(labels[view])loadTable(labels[view][1],1)}
async function initContext(){const [list,user]=await Promise.all([api('complexes/enabled'),api('auth/me')]);const items=list?.items||list||[];state.roleCodes=user.roleCodes||[];state.readOnly=state.roleCodes.includes('registered_user')&&!state.roleCodes.includes('admin');document.body.classList.toggle('read-only',state.readOnly);$('#userMenu').textContent=user.realName||user.username||'当前用户';$('#complexSelect').innerHTML=items.map(x=>`<option value="${x.complex_id}">${esc(x.complex_name)}</option>`).join('');if(!items.some(x=>Number(x.complex_id)===state.complexId))state.complexId=Number(items[0]?.complex_id||1);$('#complexSelect').value=state.complexId;$('#statDate').value=state.statDate}
function chart(id,opt){const e=$('#'+id);if(!e||!window.echarts)return;state.charts[id]?.dispose();state.charts[id]=echarts.init(e);state.charts[id].setOption({...opt,color:palette,grid:{containLabel:true,left:opt.grid?.left||55,right:opt.grid?.right||30,top:opt.grid?.top||35,bottom:opt.grid?.bottom||45}})}
async function loadDashboard(){try{const s=await api('dashboard/summary?'+qs());const cards=[['建筑数量',s.buildingCount,'栋','buildings'],['计量设备数量',s.deviceCount,'台','devices'],['近30日综合能耗',s.recentEnergyTce,'tce','energy'],['近30日碳排放',s.recentCarbonKg>=1000?fmt(s.recentCarbonKg/1000)+' tCO₂e':fmt(s.recentCarbonKg)+' kgCO₂e','', 'carbon'],['年度预算执行率',fmt(s.budgetExecutionRate)+'%','','budget'],['未关闭预警',s.openAlerts,'条','alerts'],['实施中节能项目',s.activeProjects,'项','projects'],['累计减排量',s.simulatedReductionKg>=1000?fmt(s.simulatedReductionKg/1000)+' tCO₂e':fmt(s.simulatedReductionKg)+' kgCO₂e','', 'projects']];$('#kpis').innerHTML=cards.map((x,i)=>`<div class="kpi" data-drill="${x[3]}"><small>${x[0]}</small><strong>${x[1]}</strong><span>${x[2]}</span></div>`).join('');document.querySelectorAll('[data-drill]').forEach(e=>e.onclick=()=>route(e.dataset.drill));const [trend,rank,mix,heat,radar,gauge]=await Promise.all([api('charts/energy-carbon-trend?'+qs()),api('charts/area-carbon-ranking?'+qs()),api('charts/energy-mix?'+qs()),api('charts/area-date-heatmap?'+qs()),api('charts/area-performance-radar?'+qs()),api('charts/budget-gauge?'+qs())]);chart('trendChart',{legend:{data:['综合能耗(tce)','碳排放(tCO₂e)']},xAxis:{type:'category',data:trend.map(x=>x.stat_date)},yAxis:[{type:'value',name:'tce'},{type:'value',name:'tCO₂e'}],series:[{name:'综合能耗(tce)',type:'line',data:trend.map(x=>x.energy_tce)},{name:'碳排放(tCO₂e)',type:'line',yAxisIndex:1,data:trend.map(x=>x.carbon_t)}]});const names=rank.map(x=>x.area_name).reverse();chart('rankingChart',{xAxis:{type:'value',name:'tCO₂e'},yAxis:{type:'category',data:names,axisLabel:{width:120,overflow:'truncate'}},series:[{type:'bar',data:rank.map(x=>x.carbon_t).reverse(),label:{show:true,position:'right',formatter:p=>fmt(p.value)}}],grid:{left:145,right:35,top:40,bottom:35}});chart('mixChart',{tooltip:{trigger:'item'},legend:{bottom:0},series:[{type:'pie',radius:['42%','70%'],data:mix.map(x=>({name:x.energy_name,value:Number(x.total_carbon_emission_kg||0)/1000}))}]});const dates=[...new Set(heat.map(x=>String(x.stat_date)))],areas=[...new Set(heat.map(x=>x.area_name))],hm=new Map(heat.map(x=>[`${x.stat_date}|${x.area_name}`,Number(x.value_tce||0)]));chart('heatChart',{xAxis:{type:'category',data:dates,axisLabel:{interval:Math.max(0,Math.floor(dates.length/10)-1)}},yAxis:{type:'category',data:areas,axisLabel:{width:120,overflow:'truncate'}},visualMap:{min:0,max:Math.max(...heat.map(x=>Number(x.value_tce)||0),1),orient:'horizontal',left:'center',bottom:4},series:[{type:'heatmap',data:dates.flatMap((d,i)=>areas.map((a,j)=>[i,j,hm.get(`${d}|${a}`)||0]))}]});const rmax=k=>Math.max(...radar.map(x=>Number(x[k])||0),1);chart('radarChart',{legend:{data:radar.slice(0,5).map(x=>x.area_name)},radar:{indicator:[{name:'单位能耗',max:rmax('unit_energy_tce')},{name:'单位碳排',max:rmax('unit_carbon_kg')},{name:'预算执行',max:100},{name:'预警数',max:rmax('alerts')} ]},series:[{type:'radar',data:radar.slice(0,5).map(x=>({name:x.area_name,value:[Number(x.unit_energy_tce)||0,Number(x.unit_carbon_kg)||0,Number(x.budget_rate)||0,Number(x.alerts)||0]}))}]});const g=Array.isArray(gauge)&&gauge[0]?gauge[0]:{};chart('gaugeChart',{series:[{type:'gauge',startAngle:180,endAngle:0,min:0,max:120,splitNumber:0,axisLabel:{show:false},pointer:{length:'55%'},detail:{formatter:'{value}%',offsetCenter:[0,'25%']},data:[{value:Number(g.execution_rate)||0,name:'执行率'}]}]});$('#gaugeMeta').innerHTML=`实际排放：${fmt(g.actual_emission_kg)} kgCO₂e　年度预算：${fmt(g.total_budget_emission_kg)} kgCO₂e　剩余：${fmt(g.remaining_budget_kg)} kgCO₂e`}catch(e){toast(e.message)}}
function renderPage(d,resource,page){const rows=d.items||d||[];const defs=columns[Object.keys(labels).find(k=>labels[k][1]===resource)]||[];if(!rows.length){$('#thead').innerHTML='';$('#tbody').innerHTML='';$('#tableState').textContent='暂无数据';return}const pk=Object.keys(rows[0])[0];$('#thead').innerHTML='<tr>'+defs.map(x=>TableSort.header(resource,x[0],x[1])).join('')+'<th>操作</th></tr>';TableSort.bind('#thead',resource,()=>loadTable(resource,1));$('#tbody').innerHTML=rows.map(r=>`<tr>${defs.map(([k])=>`<td>${esc(displayCell(resource,k,r[k]))}</td>`).join('')}<td><button class="btn ghost" data-action="view" data-id="${r[pk]}">查看</button>${['complexes','buildings','areas','merchants','meter-devices','energy-records'].includes(resource)?`<button class="btn mint" data-action="edit" data-id="${r[pk]}">编辑</button>`:''}${['complexes','buildings','areas','merchants','meter-devices'].includes(resource)?`<button class="btn danger" data-action="delete" data-id="${r[pk]}">停用</button>`:''}${resource==='alerts'?`<button class="btn mint" data-action="ack" data-id="${r[pk]}">确认</button><button class="btn danger" data-action="close" data-id="${r[pk]}">关闭</button>`:''}</td></tr>`).join('');const total=d.total??rows.length;$('#tableState').innerHTML=`共 ${total} 条　第 ${page} 页 <button class="btn ghost" id="prev" ${page<=1?'disabled':''}>上一页</button><button class="btn ghost" id="next" ${page*state.pageSize>=total?'disabled':''}>下一页</button>`;$('#prev')?.addEventListener('click',()=>loadTable(resource,page-1));$('#next')?.addEventListener('click',()=>loadTable(resource,page+1));document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>rowAction(resource,b.dataset.action,b.dataset.id))}
async function loadTable(resource,page=1){state.resource=resource;state.page=page;const key=Object.keys(labels).find(k=>labels[k][1]===resource);$('#tableTitle').textContent=labels[key]?.[0]||'数据列表';try{const d=await api(`${resource}?${qs()}&keyword=${encodeURIComponent($('#keyword').value||'')}&page=${page}&pageSize=${state.pageSize}`);renderPage(d,resource,page)}catch(e){$('#tableState').textContent=e.message}}
async function rowAction(resource,action,id){if(action==='delete'&&!confirm('确认停用当前记录？'))return;try{if(action==='delete'){await api(`${resource}/${id}`,{method:'DELETE'});toast('已停用');return loadTable(resource,state.page)}if(action==='ack'||action==='close'){if(!confirm(action==='close'?'确认关闭预警？':'确认预警并开始处理？'))return;await api(`alerts/${id}/${action==='close'?'close':'acknowledge'}`,{method:'PUT',headers:{'Content-Type':'application/json'},body:'{}'});toast('预警状态已更新');return loadTable(resource,state.page)}const d=await api(`${resource}/${id}`);const row=Array.isArray(d)?d[0]:d;if(action==='view'){alert(JSON.stringify(row,null,2));return}if(action==='edit')openEditor(resource,row)}catch(e){toast(e.message)}}
const fields={complexes:[['complexId','ID','hidden'],['complexCode','综合体编码','text'],['complexName','综合体名称','text'],['address','详细地址','text'],['grossFloorArea','建筑面积','number'],['operatorName','运营单位','text'],['propertyCompany','物业单位','text'],['contactName','联系人','text'],['contactPhone','联系电话','text'],['remark','备注','text']],buildings:[['buildingId','ID','hidden'],['complexId','综合体','number'],['buildingCode','建筑编码','text'],['buildingName','建筑名称','text'],['buildingType','建筑类型','text'],['grossFloorArea','建筑面积','number'],['remark','备注','text']],areas:[['areaId','ID','hidden'],['buildingId','建筑','number'],['areaCode','区域编码','text'],['areaName','区域名称','text'],['areaType','区域类型','text'],['floorNo','楼层','text'],['grossArea','面积','number'],['rentableArea','可租面积','number'],['remark','备注','text']],merchants:[['merchantId','ID','hidden'],['complexId','综合体','number'],['merchantCode','商户编码','text'],['merchantName','商户名称','text'],['category','分类','text'],['brandName','品牌','text'],['contactName','联系人','text'],['contactPhone','联系电话','text'],['operatingArea','经营面积','number'],['remark','备注','text']],devices:[['meterDeviceId','ID','hidden'],['meterNodeId','计量节点','number'],['energyTypeId','能源类型','number'],['deviceCode','设备编码','text'],['deviceName','设备名称','text'],['deviceType','设备类型','text'],['manufacturer','厂家','text'],['modelNumber','型号','text'],['protocol','协议','text'],['multiplier','倍率','number'],['collectionFrequencyMinutes','采集频率','number'],['installationDate','安装日期','date'],['remark','备注','text']]};
function openEditor(resource,row={}){const fs=fields[Object.keys(labels).find(k=>labels[k][1]===resource)];if(!fs)return toast('该页面暂未开放编辑表单');const editing=Object.keys(row).length>0,d=$('#editor');d.innerHTML=`<form id="editorForm"><h3>${editing?'编辑':'新增'}${labels[Object.keys(labels).find(k=>labels[k][1]===resource)][0]}</h3>${fs.map(([k,l,t])=>`<label>${l}<input name="${k}" type="${t}" value="${esc(row[k]??'')}" ${t==='hidden'?'':'required'}></label>`).join('')}<div class="form-actions"><button type="button" class="btn ghost" id="cancelEditor">取消</button><button type="submit" class="btn primary">保存</button></div></form>`;d.showModal();const close=()=>{d.close();d.innerHTML=''};$('#cancelEditor').onclick=close;d.oncancel=e=>{e.preventDefault();close()};$('#editorForm').onsubmit=async e=>{e.preventDefault();const b=Object.fromEntries(new FormData(e.target));if(!editing){b.complexId=b.complexId||String(state.complexId)}try{await api(resource,{method:editing?'PUT':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(b)});close();toast('保存成功');loadTable(resource,state.page)}catch(err){toast(err.message)}}}
function renderTree(rows){const q=($('#treeSearch').value||'').toLowerCase();const by={};rows.filter(n=>!q||`${n.node_name}${n.node_code}`.toLowerCase().includes(q)).forEach(n=>(by[n.parent_node_id||0]??=[]).push(n));const walk=p=>(by[p]||[]).map(n=>`<details open><summary class="tree-node" data-id="${n.meter_node_id}">${esc(n.node_name)} <small>${esc({root:'综合体',building:'建筑',area:'区域',merchant:'商户',meter:'设备'}[n.node_type]||'节点')} · ${n.node_status===1?'启用':'停用'}</small></summary><div class="tree-children">${walk(n.meter_node_id)}</div></details>`).join('');$('#tree').innerHTML=walk(0)||'<div class="table-state">暂无节点</div>';document.querySelectorAll('.tree-node').forEach(e=>e.onclick=ev=>{ev.preventDefault();document.querySelectorAll('.tree-node').forEach(x=>x.classList.remove('selected'));e.classList.add('selected');loadNode(e.dataset.id)})}
let treeRows=[];async function loadTree(){treeRows=await api('meter-nodes/tree?'+qs());renderTree(treeRows)}async function loadNode(id){const d=await api('meter-nodes/'+id),r=Array.isArray(d)?d[0]:d;Object.entries(r||{}).forEach(([k,v])=>{const e=$(`#nodeForm [name="${k.replace(/_([a-z])/g,(_,c)=>c.toUpperCase())}"]`);if(e)e.value=v??''})}
const queryDefs={monthly:['月度区域能耗与碳排放','analytics/monthly-area','年度、月份'],merchants:['商户碳排放排名','analytics/top-merchants','年度、月份、数量'],over:['超预算功能区域','analytics/over-budget','预算编号'],alerts:['未关闭预警','analytics/open-alerts','预警等级'],projects:['节能项目效果','analytics/project-effect',''],mix:['能源结构分析','analytics/energy-mix','年度、月份'],tree:['计量节点层级查询','meter-nodes/tree','']};let queryData=[];function loadQueries(){const tabs=Object.entries(queryDefs).map(([k,v])=>`<button class="btn ghost ${state.query===k?'active':''}" data-query="${k}">${v[0]}</button>`).join('');$('#queryTabs').innerHTML=tabs;document.querySelectorAll('[data-query]').forEach(b=>b.onclick=()=>{state.query=b.dataset.query;loadQueries()});$('#queryFilters').innerHTML='<span>当前综合体与统计日期已自动带入</span>';}
const queryColumnLabels={area_name:'功能区域',energy_name:'能源类型',merchant_name:'商户名称',project_name:'项目名称',node_name:'节点名称',node_code:'节点编码',node_type:'节点类型',node_level:'节点层级',total_consumption:'能源消费量',total_energy_consumption:'能源消费量',total_carbon_emission_kg:'碳排放（kgCO₂e）',carbon_emission_kg:'碳排放（kgCO₂e）',total_energy_cost:'能源费用（元）',budget_emission_kg:'预算排放（kgCO₂e）',actual_emission_kg:'实际排放（kgCO₂e）',execution_rate:'执行率（%）',remaining_budget_kg:'剩余预算（kgCO₂e）',event_code:'预警编码',severity_level:'预警等级',event_title:'预警标题',occurred_at:'发生时间',event_status:'预警状态',energy_saving_amount:'节能量',carbon_reduction_kg:'减排量（kgCO₂e）',return_on_investment_rate:'投资回报率（%）',payback_period_months:'回收期（月）'};
