function renderQueryResult(){if(!queryData.length){$('#queryResult').innerHTML='<div class="table-state">暂无符合条件的数据</div>';return}const resource='query-'+state.query,defs=Object.keys(queryData[0]).map(k=>[k,queryColumnLabels[k]||k.replaceAll('_',' ')]),rows=TableSort.sortRows(resource,queryData);$('#queryResult').innerHTML=`<p>共 ${rows.length} 条</p><table><thead><tr>${defs.map(x=>TableSort.header(resource,x[0],x[1])).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${defs.map(([k])=>`<td>${esc(fmt(r[k]))}</td>`).join('')}</tr>`).join('')}</tbody></table>`;TableSort.bind('#queryResult',resource,renderQueryResult)}
