function downloadCsv(filename,headers,rows){if(!rows.length)return toast('暂无可导出的数据');const quote=value=>`"${String(value??'').replaceAll('"','""')}"`;const csv=[headers.map(x=>quote(x[1])).join(','),...rows.map(row=>headers.map(x=>quote(row[x[0]])).join(','))].join('\r\n');const link=document.createElement('a');link.href=URL.createObjectURL(new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}));link.download=filename;link.click();URL.revokeObjectURL(link.href)}
