async function loadMerchantBills(){if(!$('#billMonth').dataset.initialized){$('#billYear').value=state.statDate.slice(0,4);$('#billMonth').value=Number(state.statDate.slice(5,7));$('#billMonth').dataset.initialized='1'}const year=Number($('#billYear').value),month=Number($('#billMonth').value);$('#billResult').innerHTML='<div class="table-state">账单加载中…</div>';try{const statusValue=$('#billStatus').value,sort=TableSort.query('merchant-bills');const rows=await api(`merchant-bills?${qs()}&year=${year}&month=${month}${statusValue!==''?'&status='+statusValue:''}${sort?'&'+sort:''}`);moduleRows.bills=rows||[];const total=moduleRows.bills.reduce((sum,row)=>sum+Number(row.total_energy_cost||0),0),carbon=moduleRows.bills.reduce((sum,row)=>sum+Number(row.total_carbon_kg||0),0);$('#billSummary').innerHTML=`<div><small>账单数量</small><strong>${moduleRows.bills.length}</strong></div><div><small>总费用</small><strong>¥ ${fmt(total)}</strong></div><div><small>总碳排放</small><strong>${fmt(carbon/1000)} tCO₂e</strong></div>`;$('#billResult').innerHTML=businessTable(billHeaders,moduleRows.bills,'<button class="btn ghost bill-detail" data-id="{id}">明细</button><button class="btn mint bill-confirm" data-id="{id}">确认</button><button class="btn danger bill-void" data-id="{id}">作废</button>','merchant-bills');TableSort.bind('#billResult','merchant-bills',loadMerchantBills);bindBillActions()}catch(error){$('#billResult').innerHTML=`<div class="table-state">${esc(error.message)}</div>`}}
async function previewMerchantBills(){const year=$('#billYear').value,month=$('#billMonth').value,method=$('#billMethod').value;$('#billResult').innerHTML='<div class="table-state">正在计算直计与公共能耗分摊…</div>';try{const rows=await api(`merchant-bills/preview?${qs()}&year=${year}&month=${month}&method=${method}`);const headers=[['merchant_name','商户'],['energy_name','能源类型'],['direct_consumption','直计用量'],['allocated_consumption','分摊用量'],['standard_unit','单位'],['total_cost','总费用（元）'],['total_tce','折标煤（tce）'],['total_carbon_kg','碳排放（kgCO₂e）']];$('#billResult').innerHTML=`<p class="result-count">分摊预览共 ${rows.length} 条能源明细，尚未写入账单。</p>${businessTable(headers,rows)}`}catch(error){$('#billResult').innerHTML=`<div class="table-state">${esc(error.message)}</div>`}}
async function generateMerchantBills(){if(!confirm('确认按当前规则生成该月商户账单？已确认账单不会被覆盖。'))return;try{await api('merchant-bills/generate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({complexId:state.complexId,year:Number($('#billYear').value),month:Number($('#billMonth').value),method:$('#billMethod').value})});toast('商户月账单生成成功');await loadMerchantBills()}catch(error){toast(error.message)}}
function bindBillActions(){document.querySelectorAll('.bill-detail').forEach(button=>button.onclick=()=>showBillDetail(button.dataset.id));document.querySelectorAll('.bill-confirm').forEach(button=>{const bill=moduleRows.bills.find(row=>String(row.merchant_energy_bill_id)===button.dataset.id);if(Number(bill?.data_completeness_rate||0)<95||Number(bill?.open_quality_issues||0)>0){button.disabled=true;button.title='完整率低于95%或存在待复核质量问题，只能保留草稿'}button.onclick=async()=>{if(!confirm('确认该账单？'))return;try{await api(`merchant-bills/${button.dataset.id}/confirm`,{method:'PUT',headers:{'Content-Type':'application/json'},body:'{}'});toast('账单已确认');loadMerchantBills()}catch(error){toast(error.message)}}});document.querySelectorAll('.bill-void').forEach(button=>button.onclick=async()=>{const reason=prompt('请输入作废原因');if(!reason)return;try{await api(`merchant-bills/${button.dataset.id}/void`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({reason})});toast('账单已作废');loadMerchantBills()}catch(error){toast(error.message)}})}
async function showBillDetail(id){try{const data=await api(`merchant-bills/${id}`),bill=data.bill?.[0];if(!bill)return toast('账单不存在');const headers=[['energy_name','能源类型'],['source_type','来源',v=>v==='direct'?'商户直计':'公共分摊'],['consumption_amount','用量'],['consumption_unit','单位'],['standard_coal_tce','折标煤（tce）'],['energy_cost','费用（元）'],['carbon_emission_kg','碳排放（kgCO₂e）']];const dialog=$('#editor');dialog.innerHTML=`<div id="billPrintArea"><h3>商户能耗与碳排放账单</h3><p>${esc(bill.complex_name)} · ${esc(bill.merchant_name)} · ${bill.bill_year} 年 ${bill.bill_month} 月 · v${bill.version_no}</p>${Number(bill.data_completeness_rate)<95?`<div class="warning-box">数据完整率 ${Number(bill.data_completeness_rate).toFixed(2)}%，存在待复核项时账单只能保留为草稿。</div>`:''}<div class="mini-kpis"><div><small>总费用</small><strong>¥ ${fmt(bill.total_energy_cost)}</strong></div><div><small>综合能耗</small><strong>${fmt(bill.total_energy_tce)} tce</strong></div><div><small>碳排放</small><strong>${fmt(Number(bill.total_carbon_kg)/1000)} tCO₂e</strong></div><div><small>数据完整率</small><strong>${Number(bill.data_completeness_rate).toFixed(2)}%</strong></div></div>${businessTable(headers,data.details||[])}</div><div class="dialog-actions"><button class="btn ghost" id="closeBill">关闭</button><button class="btn primary" id="printBill">打印</button></div>`;dialog.showModal();$('#closeBill').onclick=()=>dialog.close();$('#printBill').onclick=()=>printElement('billPrintArea',`能碳账单-${bill.bill_code}`)}catch(error){toast(error.message)}}
function printElement(id,title){const content=document.getElementById(id)?.innerHTML;if(!content)return;const win=window.open('','_blank');win.document.write(`<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><title>${esc(title)}</title><style>body{font-family:Microsoft YaHei,sans-serif;color:#183f36;padding:28px}table{width:100%;border-collapse:collapse}th,td{border:1px solid #d9e5dc;padding:8px;text-align:left}.mini-kpis{display:flex;gap:20px;margin:18px 0}.mini-kpis div{border:1px solid #d9e5dc;padding:12px}.mini-kpis small,.mini-kpis strong{display:block}.notice{margin-top:20px;color:#5c716a}</style></head><body>${content}</body></html>`);win.document.close();win.focus();win.print()}

function initMonthlyReport(){if(!$('#reportMonth').dataset.initialized){$('#reportYear').value=state.statDate.slice(0,4);$('#reportMonth').value=Number(state.statDate.slice(5,7));$('#reportMonth').dataset.initialized='1'}if(!moduleRows.report)generateMonthlyReport()}
const reportTables={energyMix:[['energy_name','能源类型'],['total_consumption','原始用量'],['standard_unit','单位'],['total_energy_cost','费用（元）'],['total_carbon_emission_kg','碳排放（kgCO₂e）']],dailyTrend:[['record_date','日期'],['energy_tce','综合能耗（tce）'],['carbon_tco2e','碳排放（tCO₂e）']],areaRanking:[['area_name','功能区域'],['energy_name','能源类型'],['total_consumption','用量'],['standard_unit','单位'],['total_carbon_emission_kg','碳排放（kgCO₂e）']],topMerchants:[['merchant_name','商户'],['total_energy_cost','能源费用（元）'],['total_carbon_emission_kg','碳排放（kgCO₂e）']],bills:[['merchant_name','商户'],['total_energy_cost','费用（元）'],['total_energy_tce','综合能耗（tce）'],['total_carbon_kg','碳排放（kgCO₂e）']],budget:[['budget_name','预算名称'],['total_budget_emission_kg','年度预算（kgCO₂e）'],['actual_emission_kg','实际排放（kgCO₂e）'],['execution_rate','执行率']],overBudget:[['area_name','超预算区域'],['budget_month','月份'],['budget_emission_kg','预算（kgCO₂e）'],['actual_emission_kg','实际（kgCO₂e）'],['warning_level','预警等级']],alerts:[['severity_level','预警等级'],['event_status','状态'],['issue_count','数量']],tasks:[['task_status','整改状态'],['task_count','数量']],projects:[['project_name','节能项目'],['energy_saving_amount','节能量'],['carbon_reduction_kg','减排量（kgCO₂e）'],['return_on_investment_rate','投资回报率']],quality:[['issue_rule','质量规则',v=>qualityRuleNames[v]||v],['severity_level','等级'],['issue_status','状态',v=>({0:'待处理',1:'复核中',2:'已解决',3:'误报'}[v]||v)],['issue_count','数量']]};
async function generateMonthlyReport(){const year=Number($('#reportYear').value),month=Number($('#reportMonth').value);$('#monthlyReport').innerHTML='<div class="table-state">正在从数据库生成月度报告…</div>';try{const data=await api(`monthly-reports/preview?${qs()}&year=${year}&month=${month}`);moduleRows.report=data;const overview=data.overview?.[0]||{},incomplete=Number(overview.date_completeness_rate||0)<100,highRisk=(data.quality||[]).some(row=>row.severity_level==='高'&&[0,1].includes(Number(row.issue_status)));$('#monthlyReport').innerHTML=`<div id="monthlyPrintArea"><header class="report-title"><span>商业综合体月度能碳管理报告</span><h2>${esc(overview.complex_name||'当前综合体')} ${year} 年 ${month} 月</h2><p>数据覆盖：${fmt(overview.actual_start_date)} 至 ${fmt(overview.actual_end_date)}，覆盖 ${fmt(overview.covered_days)}/${fmt(overview.expected_days)} 天；实际 ${fmt(overview.actual_record_count)} / 应有 ${fmt(overview.expected_record_count)} 条</p></header>${highRisk?'<div class="warning-box">数据质量风险提示：当前存在未解决的高风险问题，请完成复核后再用于正式管理决策。</div>':''}${incomplete?`<div class="warning-box">本报告基于当前数据库已采集数据生成，该月份数据完整率为 ${fmt(overview.date_completeness_rate)}%，部分指标仅代表已覆盖时段。</div>`:''}<section class="report-section"><h3>一、管理摘要</h3><div class="mini-kpis"><div><small>综合能耗</small><strong>${fmt(overview.total_energy_tce)} tce</strong></div><div><small>能源费用</small><strong>¥ ${fmt(overview.total_energy_cost)}</strong></div><div><small>碳排放</small><strong>${fmt(Number(overview.total_carbon_kg||0)/1000)} tCO₂e</strong></div><div><small>账单数量</small><strong>${fmt(overview.merchant_bill_count)}</strong></div></div></section><section class="report-section"><h3>二、能源消费与日趋势</h3>${businessTable(reportTables.energyMix,data.energyMix||[])}${businessTable(reportTables.dailyTrend,data.dailyTrend||[])}</section><section class="report-section"><h3>三、功能区域能碳表现</h3>${businessTable(reportTables.areaRanking,data.areaRanking||[])}</section><section class="report-section"><h3>四、高排放商户与账单</h3>${businessTable(reportTables.topMerchants,data.topMerchants||[])}${businessTable(reportTables.bills,data.bills||[])}</section><section class="report-section"><h3>五、碳预算与超预算区域</h3>${businessTable(reportTables.budget,data.budget||[])}${businessTable(reportTables.overBudget,data.overBudget||[])}</section><section class="report-section"><h3>六、预警整改与节能项目</h3><p>本月预警 ${fmt(overview.alert_count)} 条，新增整改任务 ${fmt(overview.corrective_task_count)} 项。</p>${businessTable(reportTables.alerts,data.alerts||[])}${businessTable(reportTables.tasks,data.tasks||[])}${businessTable(reportTables.projects,data.projects||[])}</section><section class="report-section"><h3>七、数据质量与管理建议</h3>${businessTable(reportTables.quality,data.quality||[])}<ul>${(data.managementAdvice||[]).map(text=>`<li>${esc(text)}</li>`).join('')}</ul></section><footer class="notice">${esc(data.disclaimer)}</footer></div>`}catch(error){$('#monthlyReport').innerHTML=`<div class="table-state">${esc(error.message)}</div>`}}
function exportMonthlyReport(){const data=moduleRows.report;if(!data)return toast('请先生成报告');const rows=[];Object.entries(reportTables).forEach(([section,headers])=>(data[section]||[]).forEach(row=>rows.push({section,...row})));const keys=[...new Set(rows.flatMap(Object.keys))];downloadCsv(`月度碳报告-${$('#reportYear').value}-${$('#reportMonth').value}.csv`,keys.map(key=>[key,key==='section'?'章节':key]),rows)}

const qualityRuleNames={missing_record:'缺失记录',duplicate_period:'重复统计周期',negative_consumption:'负数用量',end_less_than_start:'期末读数小于期初读数',sudden_increase:'能耗突增',continuous_zero:'连续零用量',device_offline:'设备离线',invalid_json:'非法或缺失 JSON',pending_audit:'待审核',expired_emission_factor:'过期排放因子',abnormal_flag:'异常标记'};
const qualityHeaders=[['data_quality_issue_id','问题编号'],['issue_rule','规则',v=>qualityRuleNames[v]||v],['severity_level','等级'],['issue_title','问题标题'],['device_name','计量设备'],['record_code','能耗记录'],['detected_at','发现时间'],['issue_status','状态',v=>({0:'待处理',1:'复核中',2:'已解决',3:'误报'}[v]||'未知')]];
async function loadDataQuality(){const stat=new Date(state.statDate+'T00:00:00');const start=new Date(stat);start.setDate(start.getDate()-29);$('#qualityStart').value=$('#qualityStart').value||start.toISOString().slice(0,10);$('#qualityEnd').value=$('#qualityEnd').value||state.statDate;if($('#qualityRule').options.length===1){const rules=await api('data-quality/rules');$('#qualityRule').innerHTML='<option value="">全部规则</option>'+rules.map(rule=>`<option value="${esc(rule.ruleCode)}">${esc(rule.ruleName)}</option>`).join('')}await refreshQuality()}
async function refreshQuality(page=qualityPage){qualityPage=page;try{const sort=TableSort.query('data-quality'),params=`${qs()}&startDate=${$('#qualityStart').value}&endDate=${$('#qualityEnd').value}&rule=${encodeURIComponent($('#qualityRule').value)}&severity=${encodeURIComponent($('#qualitySeverity').value)}&status=${encodeURIComponent($('#qualityStatus').value)}&deviceId=${encodeURIComponent($('#qualityDevice').value)}&keyword=${encodeURIComponent($('#qualityKeyword').value)}&page=${page}&pageSize=20${sort?'&'+sort:''}`;const [summaryRows,result]=await Promise.all([api(`data-quality/summary?${qs()}`),api(`data-quality/issues?${params}`)]);const summary=summaryRows?.[0]||{};$('#qualitySummary').innerHTML=`<div><small>开放问题</small><strong>${fmt(Number(summary.pending_count||0)+Number(summary.reviewing_count||0))}</strong></div><div><small>严重问题</small><strong>${fmt(summary.high_open_count)}</strong></div><div><small>缺失数据</small><strong>${fmt(summary.missing_count)}</strong></div><div><small>异常突增</small><strong>${fmt(summary.sudden_count)}</strong></div><div><small>离线设备</small><strong>${fmt(summary.offline_count)}</strong></div><div><small>待审核记录</small><strong>${fmt(summary.pending_audit_count)}</strong></div><div><small>失效因子</small><strong>${fmt(summary.expired_factor_count)}</strong></div><div><small>近30日完整率</small><strong>${fmt(summary.data_completeness_rate)}%</strong></div>`;moduleRows.quality=result.items||[];$('#qualityResult').innerHTML=businessTable(qualityHeaders,moduleRows.quality,'<button class="btn ghost quality-detail" data-id="{id}">详情</button><button class="btn mint quality-review" data-id="{id}">复核</button><button class="btn primary quality-resolve" data-id="{id}">解决</button><button class="btn danger quality-false" data-id="{id}">标记误报</button>','data-quality');TableSort.bind('#qualityResult','data-quality',()=>refreshQuality(1));const total=Number(result.total||0);$('#qualityPager').innerHTML=`共 ${total} 条　第 ${page} 页 <button class="btn ghost" id="qualityPrev" ${page<=1?'disabled':''}>上一页</button><button class="btn ghost" id="qualityNext" ${page*20>=total?'disabled':''}>下一页</button>`;$('#qualityPrev')?.addEventListener('click',()=>refreshQuality(page-1));$('#qualityNext')?.addEventListener('click',()=>refreshQuality(page+1));bindQualityActions()}catch(error){$('#qualityResult').innerHTML=`<div class="table-state">${esc(error.message)}</div>`}}
async function scanDataQuality(){try{await api('data-quality/scan',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({complexId:state.complexId,startDate:$('#qualityStart').value,endDate:$('#qualityEnd').value})});toast('数据质量扫描完成');refreshQuality()}catch(error){toast(error.message)}}
function bindQualityActions(){document.querySelectorAll('.quality-detail').forEach(button=>button.onclick=()=>showQualityDetail(button.dataset.id));[['quality-review','review','复核意见'],['quality-resolve','resolve','解决说明'],['quality-false','false-positive','误报说明']].forEach(([className,action,label])=>document.querySelectorAll('.'+className).forEach(button=>button.onclick=async()=>{const comment=prompt(`请输入${label}`);if(!comment)return;try{await api(`data-quality/issues/${button.dataset.id}/${action}`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({comment})});toast('处理状态已更新');refreshQuality()}catch(error){toast(error.message)}}))}
async function showQualityDetail(id){try{const data=await api(`data-quality/issues/${id}`),issue=data.issue?.[0];if(!issue)return toast('问题不存在');const dialog=$('#editor');dialog.innerHTML=`<h3>数据质量问题 #${esc(id)}</h3><div class="detail-grid"><div><small>规则</small>${esc(qualityRuleNames[issue.issue_rule]||issue.issue_rule)}</div><div><small>严重程度</small>${esc(issue.severity_level)}</div><div><small>设备</small>${esc(fmt(issue.device_name))}</div><div><small>能耗记录</small>${esc(fmt(issue.record_code))}</div><div><small>期初 / 期末读数</small>${esc(fmt(issue.start_reading))} / ${esc(fmt(issue.end_reading))}</div><div><small>当前碳排放</small>${esc(fmt(issue.carbon_emission_kg))} kgCO₂e</div><div class="full"><small>问题说明</small>${esc(issue.issue_description)}</div><div class="full"><small>检测值 / 期望值</small>${esc(fmt(issue.detected_value))} / ${esc(fmt(issue.expected_value))}</div><div class="full"><small>原始报文</small><pre>${esc(JSON.stringify(issue.raw_payload??{},null,2))}</pre></div></div><h4>复核轨迹</h4>${businessTable([['reviewed_at','时间'],['real_name','复核人'],['review_action','动作'],['review_comment','说明']],data.reviews||[])}<div class="dialog-actions"><button class="btn ghost" id="closeQuality">关闭</button>${issue.energy_record_id?'<button class="btn mint" id="qualityCorrect">修正记录</button>':''}<button class="btn danger" id="qualityAlert">创建预警</button></div>`;dialog.showModal();$('#closeQuality').onclick=()=>dialog.close();$('#qualityCorrect')?.addEventListener('click',()=>openQualityCorrection(id,issue));$('#qualityAlert').onclick=async()=>{try{const result=await api(`data-quality/issues/${id}/create-alert`,{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});toast(result.reused?'已关联现有未关闭预警':'已创建预警事件');dialog.close()}catch(error){toast(error.message)}}}catch(error){toast(error.message)}}
function openQualityCorrection(id,issue){const dialog=$('#editor');dialog.innerHTML=`<form id="qualityCorrectionForm"><h3>修正能耗记录</h3><p class="notice">修正将保存前后快照，并由数据库现有触发器同步更新碳核算记录。</p><label>期初读数<input name="startReading" type="number" step="0.000001" min="0" value="${esc(issue.start_reading)}" required></label><label>期末读数<input name="endReading" type="number" step="0.000001" min="0" value="${esc(issue.end_reading)}" required></label><label>修正原因<textarea name="reason" required></textarea></label><div class="form-actions"><button type="button" class="btn ghost" id="cancelCorrection">取消</button><button class="btn primary">确认修正</button></div></form>`;$('#cancelCorrection').onclick=()=>dialog.close();$('#qualityCorrectionForm').onsubmit=async event=>{event.preventDefault();if(!confirm('确认修正该能耗记录并重新核算碳排放？'))return;try{const result=await api(`data-quality/issues/${id}/correct`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(event.target)))});dialog.close();toast(`修正成功，碳排放更新为 ${fmt(result.after.carbon_emission_kg)} kgCO₂e`);refreshQuality()}catch(error){toast(error.message)}}}

document.addEventListener('DOMContentLoaded',()=>{const billMonth=$('#billMonth'),reportMonth=$('#reportMonth');if(billMonth)billMonth.innerHTML=monthOptions();if(reportMonth)reportMonth.innerHTML=monthOptions();$('#billSearch')?.addEventListener('click',loadMerchantBills);$('#billPreview')?.addEventListener('click',previewMerchantBills);$('#billGenerate')?.addEventListener('click',generateMerchantBills);$('#billExport')?.addEventListener('click',()=>downloadCsv('商户能碳账单.csv',billHeaders,moduleRows.bills));$('#reportGenerate')?.addEventListener('click',generateMonthlyReport);$('#reportPrint')?.addEventListener('click',()=>printElement('monthlyPrintArea','月度碳排放管理报告'));$('#reportExport')?.addEventListener('click',exportMonthlyReport);$('#qualityScan')?.addEventListener('click',scanDataQuality);$('#qualitySearch')?.addEventListener('click',()=>refreshQuality(1));$('#qualityReset')?.addEventListener('click',()=>{TableSort.clear('data-quality');$('#qualityRule').value='';$('#qualitySeverity').value='';$('#qualityStatus').value='';$('#qualityDevice').value='';$('#qualityKeyword').value='';refreshQuality(1)})});
/* Keep radar labels readable and expose normalized performance alongside raw values. */
function renderRadarChart(rows,selectedNames){const selected=rows.filter(x=>selectedNames.includes(x.area_name));if(!selected.length){return}const max=k=>Math.max(...selected.map(x=>Number(x[k])||0),1);const normalize=(value,key)=>{const ratio=Math.min(1,(Number(value)||0)/max(key));return Math.round((1-ratio)*1000)/10};const series=selected.map(x=>{const raw={energy:Number(x.unit_energy_tce)||0,carbon:Number(x.unit_carbon_kg)||0,budget:Number(x.budget_rate)||0,alerts:Number(x.alerts)||0};return {name:x.area_name,value:[normalize(raw.energy,'unit_energy_tce'),normalize(raw.carbon,'unit_carbon_kg'),Math.max(0,Math.min(100,100-raw.budget)),normalize(raw.alerts,'alerts')],raw}});chart('radarChart',{tooltip:{trigger:'item',formatter:p=>{const item=series.find(x=>x.name===p.name);if(!item)return p.name;return `${esc(p.name)}<br>单位能耗：${fmt(item.raw.energy)} tce/㎡（绩效 ${p.value[0]}）<br>单位碳排：${fmt(item.raw.carbon)} kgCO₂e/㎡（绩效 ${p.value[1]}）<br>预算执行：${fmt(item.raw.budget)}%（绩效 ${p.value[2]}）<br>未关闭预警：${fmt(item.raw.alerts)}（绩效 ${p.value[3]}）`}},legend:{top:4,left:'center',type:'scroll',data:selected.map(x=>x.area_name)},radar:{center:['50%','61%'],radius:'52%',splitNumber:4,indicator:[{name:'单位能耗绩效',max:100},{name:'单位碳排绩效',max:100},{name:'预算绩效',max:100},{name:'预警绩效',max:100}],axisName:{color:'#5c716a'}},series:[{type:'radar',symbolSize:4,data:series}]})}
document.addEventListener('DOMContentLoaded',()=>{const brand=document.querySelector('.sidebar .logo');if(brand){brand.setAttribute('role','link');brand.setAttribute('tabindex','0');brand.setAttribute('aria-label','返回总览驾驶舱');const goHome=()=>route('dashboard');brand.addEventListener('click',goHome);brand.addEventListener('keydown',event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();goHome()}})}});
document.addEventListener('DOMContentLoaded',()=>{const brand=document.querySelector('.sidebar .logo');if(!brand)return;const probe=new Image();probe.onerror=()=>{brand.classList.add('logo-missing');const title=brand.querySelector('strong');if(title)title.textContent='低碳管理'};probe.src='assets/images/brand-logo.png?v=20260814b'});
document.addEventListener('DOMContentLoaded',()=>{$('#exportLogs')?.addEventListener('click',()=>exportOperationLogs().catch(error=>toast(error.message)));['#logModule','#logType','#logStart','#logEnd'].forEach(id=>$(id)?.addEventListener('change',()=>state.resource==='logs'&&loadTable('logs',1)))});
function chart(id,opt){const element=document.querySelector('#'+id);if(!element||!window.echarts)return null;let instance=echarts.getInstanceByDom(element);if(instance)instance.dispose();instance=echarts.init(element);state.charts[id]=instance;const option={...opt,color:palette};if(option.grid!==undefined)option.grid={containLabel:true,...option.grid};if(id==='gaugeChart'&&option.series?.[0]){const gauge=option.series[0];gauge.center=['50%','62%'];gauge.radius='78%';gauge.startAngle=180;gauge.endAngle=0;gauge.splitNumber=0;gauge.axisTick={show:false};gauge.splitLine={show:false};gauge.axisLabel={show:false};gauge.title={show:false};gauge.detail={valueAnimation:true,formatter:value=>`${Number(value).toFixed(2)}%`,fontSize:27,offsetCenter:[0,'10%'],color:'#1d5547'}}instance.clear();instance.setOption(option,true);requestAnimationFrame(()=>instance.resize());return instance}

const loadDashboardWithData=loadDashboard;
loadDashboard=async function(){await loadDashboardWithData();const ranking=state.charts.rankingChart;if(ranking){ranking.setOption({grid:{left:24,right:78,top:30,bottom:52,containLabel:true},xAxis:{name:'tCO₂e',nameLocation:'middle',nameGap:32},yAxis:{axisLabel:{width:112,overflow:'truncate'}},dataZoom:(ranking.getOption().dataZoom||[]).map(item=>item.type==='slider'?{...item,width:7,right:12,showDetail:false,brushSelect:false,borderColor:'transparent',fillerColor:'rgba(88,167,154,.18)',handleSize:'75%'}:item)},false)}const heat=state.charts.heatChart;if(heat){heat.setOption({grid:{left:30,right:30,top:30,bottom:108,containLabel:true},xAxis:{axisLabel:{interval:'auto',rotate:35,margin:12}},yAxis:{axisLabel:{width:110,overflow:'truncate'}},visualMap:{orient:'horizontal',left:'center',bottom:8,itemWidth:12,itemHeight:132,textGap:8}},false)}const radar=state.charts.radarChart;if(radar){radar.setOption({legend:{top:4,left:'center'},radar:{center:['50%','61%'],radius:'52%'}},false)}const gauge=state.charts.gaugeChart;if(gauge){gauge.setOption({series:[{center:['50%','62%'],radius:'78%',detail:{offsetCenter:[0,'10%']}}]},false)}requestAnimationFrame(()=>requestAnimationFrame(()=>Object.values(state.charts).forEach(instance=>instance?.resize())))};
